-- Read the result back. This script asserts its OWN rows and nothing else.
SELECT 'all 5 notable NPCs are in' AS assertion, count(*) AS got, 5 AS want
  FROM notable_npcs WHERE slug IN ('sir-jude', 'sir-lunais-the-brute', 'sir-trey-risharde', 'sir-john-of-conrad', 'lady-night-runner');
SELECT 'and the notables 23' AS assertion, count(*) AS got, 23 AS want
  FROM stat_attacks WHERE owner_kind = 'notable_npc' AND owner_slug IN ('sir-jude', 'sir-lunais-the-brute', 'sir-trey-risharde', 'sir-john-of-conrad', 'lady-night-runner');

