INSERT INTO notable_npcs (slug, name, real_name, title, system, race, occ, level, alignment, age, height, weight, attributes, hp, sdc, mdc, ppe, isp, ar, horror_factor, combat, bonuses_note, skills, skills_note, natural_abilities, magic, psionics, super_powers, cybernetics, weapons_and_equipment, money, disposition, allies, enemies, description, source_book) VALUES
('sir-jude', 'Sir Jude', 'Jude Acedelma II', 'Captain of the Black Swords', 'rifts', 'Human', '8th level Crusader Cyber-Knight', 8, 'Aberrant (was Scrupulous)', '41', '6 feet (1.8 m)', '180 lbs (81 kg)', '{"IQ":11,"ME":19,"MA":21,"PS":22,"PP":13,"PE":18,"PB":8,"Spd":18}', 41, 85, NULL, 20, 40, 17, NULL, '{"attacks":7,"initiative":4,"strike":2,"parry":4,"dodge":4,"pull":5,"roll":6,"entangle":1,"disarm":4,"damage":6}', 'Hand to Hand: Martial Arts, with Fencing and Cyber-Knight Zen Combat. Body flip/throw, all hand strikes, all foot strikes including leap kick, all holds, back flip and back flip escape; critical strike on an unmodified 18-20. +1 to strike and parry with a sword or dagger, +1D6 damage with a sword. 65% trust/intimidate, +2 to save vs psionics/insanity, +6 to save vs Horror Factor, +3 to Perception Rolls. Zen Combat: W.P. Paired Weapons, W.P. Shield, combat acrobatics, basic and advanced combat awareness, +4 to automatic dodge against tech, cloud sensors. Male.', '[{"name":"Language: American","pct":98},{"name":"Language: Dragonese/Elven","pct":98},{"name":"Language: Euro","pct":98},{"name":"Language: Spanish","pct":98},{"name":"Literacy: American","pct":85},{"name":"Anthropology","pct":80},{"name":"Climbing","pct":90},{"name":"Horsemanship: Cyber-Knight","pct":91},{"name":"Land Navigation","pct":76},{"name":"Lore: Demons & Monsters","pct":85},{"name":"Paramedic","pct":85},{"name":"Swimming","pct":95},{"name":"Detect Ambush","pct":70},{"name":"Intelligence","pct":65},{"name":"Tracking","pct":65},{"name":"Wilderness Survival","pct":70},{"name":"Literacy: Spanish","pct":75},{"name":"Mathematics: Basic","pct":80},{"name":"Pilot: Hover Craft (Ground)","pct":75},{"name":"Sensory Equipment","pct":55},{"name":"Electronic Countermeasures","pct":40},{"name":"Radio: Basic","pct":55},{"name":"Cook","pct":70},{"name":"Horsemanship: Exotic","pct":65},{"name":"Pilot: Automobile","pct":74},{"name":"Play Musical Instrument: Spanish Guitar","pct":70},{"name":"Sing","pct":70},{"name":"Spelunking","pct":70},{"name":"Dowsing","pct":35},{"name":"Identify Plants & Fruit","pct":40}]', 'Body Building, Athletics (General), Fencing and Forced March. Gymnastics: Sense of Balance 76%, Work Parallel Bars and Rings 86%, Climb Rope 79%, Back Flip 89%, Prowl 30%. Climbing is printed 90%/80%, Horsemanship: Cyber-Knight 91%/71% and Horsemanship: Exotic 65%/55%. The book files Detect Ambush, Intelligence, Tracking and Wilderness Survival as Espionage skills. W.P. Archery, Knife, Shield, Sword, Energy Pistol, Energy Rifle and Rifles at 8th level; W.P. Axe, Quick Draw and Handguns at 4th level.', 'Every standard Cyber-Knight ability, among them two Psi-Swords at once. Shrugs off Horror Factor generally and is wholly immune to that of Master, Secondary and Wild vampires; the save bonus is counted in his bonuses. Knows vampires and many other supernatural beings well from lore and long hunting.', 'None.', 'Major psychic; needs a 12 to save vs psionics. Summon Psi-Sword (no I.S.P. cost), Create Psi-Shield (15), Meditation (0). No other powers.', NULL, 'Cyber-Armor only, A.R. 17: Shoulders (2) 14 M.D.C. each, Back Shoulder Blades (2) 20 each, Forearms (2) 15 each, Thighs/Upper Legs (2) 20 each, Chest Plate (Main Body) 74.', 'Vibro-Lance (3D6+6 M.D. from horseback, plus 3D6 on a charge that counts as two attacks; 13 feet (4 m); usable only mounted). Compound Bow (heavy explosive arrows 2D6 M.D., wooden arrows 2D6 S.D.C./Hit Points; rate of fire 6; 860 feet (262 m)). WI-AL18 Assault Laser Rifle (2D6+2 M.D. single shot or 6D6+3 triple pulse; 1,600 feet (488 m); +1 to strike; 21 shots per standard E-Clip). Extra ammo: 24 heavy explosive arrows, 36 wooden arrows, 12 standard E-Clips. Heavy environmental armor in bone-like matte white and gray: Main Body 120, Arms 35 each, Legs 55 each, Head/Helmet 50 M.D.C.; -10% to climb, -20% to prowl, swim, acrobatics and similar skills. Light black non-environmental armor for freer movement: Main Body 35, Helmet 25, Arms and Legs 10 each, no penalties. Gas mask and air filter, high-powered binoculars, large flashlight, 200 feet (61.0 m) of nylon cord, three pairs of handcuffs, survival knife, portable fishing rod and tackle, cooking salt and spices, first-aid kit, two RMK Robot Medical Kits, an IRMSS and plenty of camping gear. Vehicle: Troy, a robot war horse (350 Main Body M.D.C., 75 mph (120 km), leaps 15 feet (4.6 m) high and 40 feet (12.2 m) long with a running start; Rifts World Book 14: New West p.199).', NULL, 'Driven past sanity by a crusade nobody would join him in. Cold, joyless and willing to spend any life, his own included, to force the Cyber-Knights into a war on the Vampire Kingdoms of Mexico. He hates vampires as much as ever, so he will not shield or rescue Xavier, and he hangs back once the siege of Arzno begins: he wants Arzno''s heroes enraged and marching south, not dead.', 'The Black Swords; the Fort Tombstone vampires, whom he serves with wide autonomy while knowing General Xavier Stuart is using him.', 'Every vampire at heart; the Cyber-Knight order he believes abandoned the South; anyone who attacks him or questions his honor.', 'Plain to look at: medium height and build, blond hair to the collar, brown eyes, a flat nose and chin. Once cheerful and fond of music and sport, he now never smiles or shows feeling, and seems as hollow as the undead he rides with. Once a renowned vampire hunter, he despaired of rousing the order against the Vampire Kingdoms and began riding with vampire packs, first watching their slaughter and then defending them, so that atrocities on the order''s doorstep would drag Lord Coake south. General Xavier Stuart recruited him, and he leads the Black Swords in the hope of provoking a great crusade.', 'Rifts World Book 28: Arzno - Vampire Incursion p.148-151'),
('sir-lunais-the-brute', 'Sir Lunais the Brute', NULL, 'Black Sword knight, Sir Jude''s blood brother', 'rifts', 'Rahu-Man (four-armed giant)', '7th level Champion Cyber-Knight', 7, 'Aberrant (was Principled)', '212', '14 feet (4.3 m)', '455 lbs (205 kg)', '{"IQ":20,"ME":18,"MA":15,"PS":35,"PP":12,"PE":21,"PB":12,"Spd":15}', NULL, NULL, 200, 48, 126, 17, 10, '{"attacks":10,"initiative":6,"strike":3,"parry":8,"dodge":4,"pull":9,"roll":8,"entangle":1,"disarm":4}', 'Hand to Hand: Martial Arts, with Wrestling and Cyber-Knight Zen Combat. Body flip/throw, all hand strikes, all foot strikes including leap kick, all holds, body block/tackle; critical strike and pin/incapacitate on an unmodified 18-20. Restrained punch 6D6 S.D.C. (the book refers to a damage bonus it does not print), full-strength punch 4D6 M.D., power punch 1D4x10 M.D. (two attacks). +2 to save vs psionics/insanity, +2 vs possession, +12% vs coma/death, +3 vs poison/magic, +5 vs Horror Factor, +3 to Perception Rolls. Zen Combat: W.P. Paired Weapons, W.P. Shield, combat acrobatics, basic combat awareness, +4 to automatic dodge against tech, cloud sensors. P.S. and P.E. are Supernatural. Male.', '[{"name":"Language: Dragonese/Elven","pct":98},{"name":"Language: Faerie","pct":98},{"name":"Language: Gobblely","pct":98},{"name":"Literacy: Dragonese/Elven","pct":86},{"name":"Literacy: Faerie","pct":86},{"name":"Literacy: Gobblely","pct":86},{"name":"Mathematics: Basic","pct":98},{"name":"Literacy: American","pct":86},{"name":"Language: American","pct":98},{"name":"Language: Canadian","pct":98},{"name":"Language: Euro","pct":98},{"name":"Lore: Demons & Monsters","pct":91},{"name":"Anthropology","pct":71},{"name":"Paramedic","pct":91},{"name":"Land Navigation","pct":78},{"name":"Horsemanship: Cyber-Knight","pct":94},{"name":"Climbing","pct":98},{"name":"Swimming","pct":96},{"name":"History","pct":81},{"name":"Law","pct":66},{"name":"Language: Spanish","pct":66},{"name":"Literacy: Spanish","pct":46},{"name":"Literacy: Euro","pct":71},{"name":"Lore: Magic","pct":76},{"name":"Lore: Religion","pct":81},{"name":"Writing","pct":66},{"name":"Astronomy","pct":51},{"name":"Mathematics: Advanced","pct":71},{"name":"Wilderness Survival","pct":71},{"name":"Cooking","pct":71},{"name":"Fishing","pct":76},{"name":"Pilot: Hover Craft","pct":86},{"name":"Pilot: Truck","pct":70},{"name":"Radio: Basic","pct":86},{"name":"Read Sensory Equipment","pct":66}]', 'Body Building, Athletics (General) and Wrestling. Gymnastics: Sense of Balance 91%, Work Parallel Bars and Rings 89%, Climb Rope 93%, Back Flip 98%, Prowl 21%. Climbing is printed 98%/93% and Horsemanship: Cyber-Knight 94%/74%. The book prints the three R.C.C. languages as Speak, and files History through Writing as Technical skills. Figures already include +6% to all skills. W.P. Blunt, Chain, Pole Arm, Shield, Staff, Sword, Energy Rifle and Heavy M.D. Weapons at 7th level; W.P. Spear, Rifles and Military Weapons at 3rd level.', 'Supernatural P.S. and P.E., natural Mega-Damage body and four arms; the book folds every bonus and penalty of the extra limbs and his size into the figures above. His Cyber-Armor is about half again as strong as a human''s, and grows and heals as normal. His race is naturally psionic. Reads and writes widely, and holds his true name secret, since on his home world a known name can be turned against its bearer by magic.', 'Lore only.', 'Major psychic; needs a 12 to save vs psionics. Summon Psi-Sword (no I.S.P. cost), Create Psi-Shield (15), Meditation (0), Intuitive Combat (10), Mind Block (4), Object Read (6), Presence Sense (4), Remote Viewing (10), See Aura (6), Sense Evil (2), Sixth Sense (2), Speed Reading (2), Telepathy (4), Total Recall (2).', NULL, 'Cyber-Armor only, A.R. 17: Shoulders (2) 16 M.D.C. each, Back Shoulder Blades (2) 27 each, Forearms (4) 19 each, Thighs/Upper Legs (2) 27 each, Chest Plate (Main Body) 90.', 'Two magic halberds, each wielded one-handed (4D6 M.D., +6 damage mounted, +3D6 on a charge that counts as two attacks; 9 feet (2.7 m); +2 to strike and parry; never dull, indestructible, double damage to demons; worth hundreds of thousands of credits each). Six magic wooden javelins (2D4 M.D. each; 7 feet (2.1 m); rate of fire 9; thrown 750 feet (229 m); indestructible, return to their quiver on command, and harm vampires as wood does). C-40R SAMAS Rail Gun (1D4x10 M.D. burst or 1D4 M.D. single shot; 4,000 feet (1,219 m); 400-round belt, 10 bursts; over 180 lbs (81 kg) with pack and belt). Sometimes an extra belt or a heavy energy rifle. Rarely wears more armor; monster-hide armor of about 100 M.D.C. when he does. Standard Cyber-Knight kit with two weeks of rations, at least six books, his journals and histories, giant-print copies of Erin Tarn''s and Victor Lazlo''s books, and a damaged two-thirds of a copy of Julius Caesar. Vehicle: Bucephalus, a Fury Beetle ridden with Horsemanship: Cyber-Knight at no penalty (650 Main Body M.D.C., Spd 150, about 100 mph (160 km), top speed held for 1D6x10 minutes, runs 24 hours without tiring; Rifts World Book 20: Canada p.153-154).', NULL, 'Gentle, scholarly and soft-spoken, and so bound by honor that the blood oath he once swore Sir Jude pulled him into the Black Swords. He alone of them truly believes their atrocities will goad Lord Coake into purging the Vampire Kingdoms, and he hopes to ride in that crusade to atone. Meanwhile he spares women and children where he can, holds the others back from the worst, and will not let the slain be raised as vampires, though he does little else to save them.', 'Sir Jude, his blood brother; the Black Swords; the Fort Tombstone vampires.', 'Vampires and demons by conviction; the Cyber-Knights who now count him a traitor.', 'A fourteen-foot, four-armed giant of human features, with long wild black hair and kindly eyes, as likely to hold a book as a weapon. He was a celebrated champion against the Calgary Rift, known for mercy as much as ferocity, and stayed loyal to Lord Coake through the Tolkeen war. When Sir Jude came north and invoked their old blood oath, he followed him to Arizona.', 'Rifts World Book 28: Arzno - Vampire Incursion p.151-153'),
('sir-trey-risharde', 'Sir Trey Risharde', 'Trey Risharde', 'Black Sword knight', 'rifts', 'Human', '8th level Despoiler Cyber-Knight', 8, 'Diabolic', '26', '5 feet, 7 inches (1.7 m)', '170 lbs (77 kg)', '{"IQ":13,"ME":16,"MA":14,"PS":12,"PP":11,"PE":19,"PB":6,"Spd":24}', 54, 56, NULL, 13, 34, 17, NULL, '{"attacks":6,"initiative":4,"strike":2,"parry":4,"dodge":4,"pull":5,"roll":6,"entangle":1,"disarm":4}', 'Hand to Hand: Martial Arts, with Cyber-Knight Zen Combat. Body flip/throw, all hand strikes, all foot strikes including leap kick, all holds, back flip and back flip escape; critical strike on an unmodified 18-20. +5 to damage with the bionic left arm only, which has a Bionic P.S. of 20. +8% to save vs coma/death, +2 vs poison/magic, +3 vs Horror Factor, +3 to Perception Rolls. Zen Combat: W.P. Paired Weapons, W.P. Shield, combat acrobatics, basic and advanced combat awareness, +4 to automatic dodge against tech, cloud sensors. His armor adds more (see equipment). Male.', '[{"name":"Literacy: American","pct":85},{"name":"Language: American","pct":96},{"name":"Language: Dragonese/Elven","pct":96},{"name":"Language: Spanish","pct":96},{"name":"Language: Euro","pct":96},{"name":"Lore: Demons & Monsters","pct":80},{"name":"Anthropology","pct":70},{"name":"Paramedic","pct":85},{"name":"Land Navigation","pct":76},{"name":"Horsemanship: Cyber-Knight","pct":91},{"name":"Climbing","pct":92},{"name":"Swimming","pct":95},{"name":"Pilot: Hover Craft","pct":85},{"name":"Navigation","pct":55},{"name":"Read Sensory Equipment","pct":70},{"name":"Weapon Systems","pct":55},{"name":"Armorer","pct":80},{"name":"Computer Operation","pct":80},{"name":"Computer Programming","pct":60},{"name":"Basic Electronics","pct":55},{"name":"Basic Mechanics","pct":70},{"name":"Demolitions","pct":81},{"name":"Mathematics: Advanced","pct":80},{"name":"Recognize Weapon Quality","pct":65},{"name":"Pilot: Automobile","pct":74},{"name":"Pilot: Truck","pct":68},{"name":"Literacy: Spanish","pct":65},{"name":"Optic Systems","pct":65},{"name":"Radio: Basic","pct":80},{"name":"Radio: Scramblers","pct":70}]', 'Body Building, Athletics (General) and Running. Gymnastics: Sense of Balance 90%, Work Parallel Bars and Rings 86%, Climb Rope 89%, Back Flip 98%, Prowl 30%. Climbing is printed 92%/92% and Horsemanship: Cyber-Knight 91%/71%. W.P. Battle Axe, Knife, Shield, Sword, Energy Rifle, Grenade Launcher, Heavy M.D. Weapons and Heavy Military Weapons at 8th level; W.P. Handguns, Energy Pistol and Military Flamethrowers at 4th level.', 'Standard Cyber-Knight abilities, but his bionics and cybernetics halve his psionics: his Psi-Sword or Psi-Battle Axe does 2D4 M.D. instead of 3D6, and he cannot form one in his bionic left hand.', 'None.', 'Major psychic; needs a 12 to save vs psionics. Summon Psi-Sword (no I.S.P. cost), Create Psi-Shield (15), Meditation (0), Alter Aura (2), Mind Block (4), Resist Fatigue (4). Every power works at half damage, effect and duration because of his bionics.', NULL, 'Cyber-Armor, A.R. 17, on the right side and legs: Shoulder (right) 14 M.D.C., Back Shoulder Blade (right) 20, Forearm (right) 15, Thighs/Upper Legs (2) 20 each, Chest Plate (Main Body) 69. Bionic spine, left shoulder and whole left arm and hand: Shoulder/Upper Arm (left) 50, Forearm (left) 25, Forearm Flame Thrower/Vibro-Blade 30, Hand (left) 12. The left forearm houses a Vibro-Sword and a flamethrower.', 'Bionic Vibro-Sword in the left forearm (2D4 M.D.; 2 feet (0.6 m)). Bionic Flame Thrower (6D6 S.D.C. per melee, no Mega-Damage, burns 1D4 melees; 20 feet (6.1 m); 12 shots from a canister in the arm). WI-GL4 Revolving Grenade Launcher (fragmentation 4D6 M.D. to a 12 foot (3.6 m) area, armor piercing 1D4x10 M.D. to 3 feet (0.9 m); 1,000 feet (305 m); 24 rounds; reloading takes two full melee rounds). JA-12 Laser Rifle (4D6 M.D. single shot or 1D6x10+10 triple burst, 4,000 feet (1,219 m); rifle grenades 3D6 M.D. to a 10 foot (3.0 m) radius, 2,000 feet (610 m), four-shot pump magazine; 30 shots per long E-Clip plus 30 in the canister; +1 to strike on an aimed single laser shot). Extra ammo: 12 fragmentation and 12 armor-piercing grenades, 8 rifle grenades, 10 long E-Clips. Captured CA-6EX Coalition armor in the Black Swords'' bone white and gray, cut for the bionic arm: Main Body 200, Arm (right) 100, Arm (left) 87, Legs 120 each, Head/Helmet 100 M.D.C.; -30% to prowl, -10% to swim and acrobatics; HUD, computer and video link, optics, laser distancer, laser targeting (+1 to strike), +8 P.S. to the right arm, +14 Spd, +10 feet (3.0 m) to leaps, fatigue halved (Rifts World Book 11: Coalition War Campaign p.102). A cache hidden at Howard: extra Vibro-Swords, two energy pistols, two JA-12 Laser Rifles, a TW Stake Driver, a TW Wood Rail Gun, 48 standard E-Clips and 144 rifle grenades (plasma, fragmentation and armor piercing in thirds). In the hovercycle: three weeks of food and water, an energy pistol and six long E-Clips. On his person: a silver cross and six wooden stakes. Vehicle: NG-480 Turbo hovercycle with extra armor and a mini-missile pod (185 mph (296 km); 12 mini-missiles, typically fragmentation, 5D6 M.D. to a 20 foot (6.1 m) radius; Rifts World Book 13: Lone Star p.61).', NULL, 'Hate all the way through. He loathes the Cyber-Knights and everything peaceful or lovely, enjoys the suffering the Black Swords cause, and serves the vampires for the power General Xavier has promised him, with no cause beyond that. He hoards gear for the day things go bad and he has to run.', 'General Xavier Stuart and the Fort Tombstone vampires; the Black Swords.', 'The Cyber-Knights; anything good.', 'Short and stocky, with dark brown hair and eyes, a broken nose, a scar from left ear to forehead and another on his chin under a thin black beard, always scowling, in black clothes and bone-like armor. Born with a deformed spine and arm and abused by his family in the West Virginia woods, he was taken in at 17 by an evil Cyber-Knight, Sir Edward, who had him bionically rebuilt and knighted him. He raided both sides in the Tolkeen war and preyed on Colorado caravans before Sir Jude recruited him to make the Black Swords notorious.', 'Rifts World Book 28: Arzno - Vampire Incursion p.153-156'),
('sir-john-of-conrad', 'Sir John of Conrad', 'Sir John Leona, also known as Antonio Johnson', 'Black Sword knight and adviser to General Xavier Stuart', 'rifts', 'Human', '3rd level Cyber-Knight (Robber Knight)', 3, 'Miscreant', '25', '5 feet, 8 inches (1.7 m)', '135 lbs (61 kg)', '{"IQ":11,"ME":11,"MA":7,"PS":13,"PP":10,"PE":10,"PB":9,"Spd":11}', 21, 56, NULL, 16, 16, 16, NULL, '{"attacks":5,"initiative":4,"strike":2,"parry":3,"dodge":3,"pull":6,"roll":3,"disarm":3}', 'Hand to Hand: Martial Arts, with Cyber-Knight Zen Combat. +1 to save vs Horror Factor, +3 to Perception Rolls. Zen Combat: W.P. Paired Weapons, W.P. Shield, combat acrobatics. Male.', '[{"name":"Literacy: American","pct":60},{"name":"Language: American","pct":90},{"name":"Language: Dragonese/Elven","pct":90},{"name":"Language: Spanish","pct":90},{"name":"Language: Euro","pct":90},{"name":"Lore: Demons & Monsters","pct":55},{"name":"Anthropology","pct":45},{"name":"Paramedic","pct":60},{"name":"Land Navigation","pct":56},{"name":"Horsemanship: Cyber-Knight","pct":76},{"name":"Climbing","pct":67},{"name":"Swimming","pct":70},{"name":"Intelligence","pct":35},{"name":"Detect Ambush","pct":45},{"name":"Interrogation","pct":35},{"name":"Imitate Voices & Impersonation","pct":41},{"name":"Concealment","pct":28},{"name":"Find Contraband","pct":24},{"name":"Palming","pct":30},{"name":"Prowl","pct":45},{"name":"Streetwise","pct":28},{"name":"Mathematics: Basic","pct":80},{"name":"Detect Concealment","pct":35},{"name":"Literacy: Spanish","pct":40},{"name":"Pilot: Automobile","pct":64},{"name":"Pilot: Hover Craft","pct":60},{"name":"Radio: Basic","pct":55},{"name":"Research","pct":50}]', 'Body Building and Athletics (Aerobic). Gymnastics: Sense of Balance 65%, Work Parallel Bars and Rings 71%, Climb Rope 79%, Back Flip 85%. Climbing is printed 67%/57%, Horsemanship: Cyber-Knight 76%/56% and Imitate Voices and Impersonation 41%/21%. Find Contraband is printed as Find Contraband, Weapons, and Cybernetics. The book files Intelligence through Imitate Voices as Espionage and Concealment through Streetwise as Rogue skills, and notes skill penalties from his low M.A. W.P. Blunt, Knife, Shield, Sword, Energy Pistol, Energy Rifle and Handguns at 3rd level.', 'Standard Cyber-Knight abilities, including two Psi-Swords or Psi-Daggers at once, the daggers his favorite hidden weapon. His lies and cowardice tell against him with anyone he has used or betrayed before.', 'None.', 'Major psychic; needs a 12 to save vs psionics. Summon Psi-Sword (no I.S.P. cost), Create Psi-Shield (15), Meditation (0). No other powers.', NULL, 'Cyber-Armor only, A.R. 16: Shoulders (2) 8 M.D.C. each, Back Shoulder Blades (2) 15 each, Forearms (2) 10 each, Thigh/Upper Legs (2) 15 each, Chest Plate (Main Body) 50.', 'Two concealed Vibro-Knives (1D6 M.D.). Two silver-plated daggers (1D6 S.D.C./H.P., double to vampires) and a silver cross worn under his clothes. Wilk''s 210 Pocket Pistol (1D6 M.D.; 400 feet (122 m); 3 shots, recharged directly). Wilk''s 457 Laser Pulse Rifle (3D6+2 M.D. single shot or 1D6x10 triple burst; 2,000 feet (610 m); 30 shots per long E-Clip; +1 to strike on an aimed shot). Extra ammo: 12 long E-Clips. Everyday wear: a concealed Naruni force field generator (160 M.D.C., self-regenerating) under Bandito Arms Branaghan armor and overcoat, usually without the helmet (Main Body 38, +28 with overcoat; Arms 18 each, +8; Legs 24 each, +12; Head/Helmet 40 M.D.C.; -5% to climb, prowl, swim and acrobatics in the overcoat; non-environmental). In battle or bad air: Crusader armor in Sir Jude''s colors (Main Body 55, Arms 20 each, Legs 30 each, Head/Helmet 35 M.D.C.; no penalties). Full camping and survival gear and extra food and water, packed for a quick escape. Vehicle: a horse at times, or his NG-230 Prowler hovercycle (190 mph (304 km); 80 Main Body M.D.C.; +5% to his piloting; lets him prowl at 40% while riding; Rifts World Book 13: Lone Star p.58-59).', 'Nearly a million in Coalition and Black Market credits, plus about 200,000 credits in precious metals, gems and Black Market goods.', 'A weasel: petty, bitter, cowardly, cruel and wholly selfish, he blames his father, his brother, the order and fate for everything he has done. He rides with the vampires for the pay, the power and the chance to kill Cyber-Knights and disgrace his family, enjoys his standing among them, and calls Xavier a friend, but he will be the first to run if the war turns.', 'General Xavier Stuart, whom he advises; the Fort Tombstone vampires, usually a pair of vampire minions and often 4-6 Secondary Vampires (levels 3-6); Pecos Raiders and other bandits he hires.', 'His father, Sir Donavan Leona, and his brother, Sir Pedro, whom he hopes to see die; the Cyber-Knights. Sir Jude despises him but keeps him as bait to draw his family and their allies south.', 'Thin, dark-haired and dark-eyed, of Hispanic descent, with a goatee and short hair meant to look noble that only make him look furtive; he moves like a thief. The lesser son of a famous Courtier Knight, he froze while Worm Wraiths cut down his brother, fled, and then took the credit for his brother''s later deeds, not knowing he lived. Exposed, he turned bandit under the name Antonio Johnson before joining Sir Jude. He plans, interrogates and schemes from the rear, striking from hiding with vampires at his side.', 'Rifts World Book 28: Arzno - Vampire Incursion p.156-158'),
('lady-night-runner', 'Lady Night Runner', 'Eamemeohe taa''eva', 'Guide and tracker to the Black Swords, Xavier''s ally', 'rifts', 'Human (Cheyenne)', '5th level Cyber-Knight', 5, 'Aberrant (was Anarchist)', '27', '5 feet, 8 inches (1.7 m)', '110 lbs (49.5 kg)', '{"IQ":11,"ME":7,"MA":18,"PS":19,"PP":14,"PE":19,"PB":11,"Spd":25}', 35, 96, NULL, 21, 45, NULL, NULL, '{"attacks":6,"initiative":6,"strike":2,"parry":3,"dodge":4,"pull":5,"roll":5,"entangle":1,"disarm":2,"damage":4}', 'Hand to Hand: Martial Arts, with Cyber-Knight Zen Combat. 50% trust/intimidate. -1 to save vs psionics, mind control, battles of will, insanity and possession, -2 vs illusions, -1 vs Horror Factor; +2 vs poison/magic, +8% vs coma/death, +3 to Perception Rolls. Zen Combat: W.P. Paired Weapons, combat acrobatics, basic combat awareness, +4 to automatic dodge against tech. The Bat Totem''s +4 Spd, +2 initiative and +1 dodge are included; her Ear Fetish''s +1 initiative and +1 roll are not. Female.', '[{"name":"Literacy: American","pct":70},{"name":"Language: American","pct":96},{"name":"Language: Dragonese/Elven","pct":96},{"name":"Language: Spanish","pct":96},{"name":"Language: Euro","pct":96},{"name":"Lore: Demons & Monsters","pct":65},{"name":"Anthropology","pct":55},{"name":"Paramedic","pct":70},{"name":"Land Navigation","pct":74},{"name":"Horsemanship: Cyber-Knight","pct":82},{"name":"Climbing","pct":77},{"name":"Swimming","pct":80},{"name":"Detect Ambush","pct":55},{"name":"Intelligence","pct":38},{"name":"Camouflage","pct":45},{"name":"Prowl","pct":57},{"name":"Tracking","pct":50},{"name":"Wilderness Survival","pct":60},{"name":"Lore: Indians","pct":50},{"name":"Lore: Magic","pct":40},{"name":"Lore: Religion","pct":45},{"name":"Mathematics: Basic","pct":65},{"name":"Cooking","pct":60},{"name":"Preserve Food","pct":45},{"name":"Sing","pct":55},{"name":"Skin & Prepare Animal Hides","pct":55},{"name":"Track Animals","pct":45}]', 'Body Building, Sniper, Trick Riding, Running and Hunting. Gymnastics: Sense of Balance 75%, Work Parallel Bars and Rings 77%, Climb Rope 83%, Back Flip 95%. Climbing is printed 77%/67%; Horsemanship: Cyber-Knight 82% refers to Trick Riding. Detect Ambush and Intelligence come from her Bat Totem; Camouflage through Wilderness Survival are filed as Hunting and Wilderness skills, the three Lores as Technical. Tracking does not include her Tracking Fetish''s +10%. The book notes skill penalties from her low M.E. W.P. Archery, Blunt, Knife, Spear, Tomahawk/Axe, Paired Weapons, Rifles and Handguns at 5th level; W.P. Chain and Targeting at 1st level; no W.P. Sword or Shield.', 'Standard Cyber-Knight abilities, but she has never managed a Psi-Sword or Psi-Shield: she forms two Psi-Spears or Psi-Tomahawks instead. Bat Totem: rarely surprised, and anyone prowling against her is at -20%. Was a natural Minor Psychic before her training. Took no Cyber-Armor on Traditionalist principle. Insanities: schizophrenia bordering on multiple personality, with voices urging her toward violence and evil (perhaps the Vampire Intelligence); a delusion that vampires stand above the Circle of Life; and obsessive hand-washing after each atrocity.', 'Lore only; she has begun studying magic to learn what is speaking in her head.', 'Major psychic; needs a 12 to save vs psionics. Summon Psi-Spear/Tomahawk (no I.S.P. cost), Meditation (0), Death Trance (1), Mind Block (4), Nightvision (4), See the Invisible (4), Summon Inner Strength (4).', NULL, 'None.', 'Spirit Short Bow, a major fetish (conjured spirit arrows 4D6 M.D. against Mega-Damage foes or 4D6 S.D.C. against mortals, ordinary arrows 1D6 S.D.C., all doubled against Alien Intelligences and their essence fragments; rate of fire 5; 880 feet (268 m)). Armor Fetish of turtle shell (45 M.D.C., regenerates 5 a day). Ear Fetish of bat ears braided into her hair (+1 initiative, +1 roll with impact; attackers by surprise or from behind are -2 to strike). Tracking Fetish, a necklace of bat teeth and toes (+10% to Tracking by sight or smell). Stone War Club (2D4+1 S.D.C.; 1.5 feet (0.5 m)). Hunting Rifle (4D6 S.D.C.; single shot; 2,000 feet (610 m); 5-shot internal magazine). Extra ammo: two dozen wooden arrows and 144 rifle shells. Armor from a Black-Winged Monster-Man (skull helm 35 M.D.C., wing cloak 60 M.D.C.; Rifts World Book 15: Spirit West p.106-107); refuses modern armor but will wear monster hide. Standard Cyber-Knight kit with nothing technological, all of it 19th-century: hide clothing, skin bedding. Rides a nameless Appaloosa pony bareback with a rope bridle, the best rider of the Black Swords; never uses a modern vehicle.', NULL, 'Deeply disturbed without knowing it: withdrawn and secretive, given to violent outbursts, disruptive in a group yet glad of company. She despises civilization, the White Man, technology and Techno-Wizardry alike, and through her Bat Totem sees vampires as kindred spirits and heralds of a more natural order.', 'General Xavier Stuart, her sworn ally, who has promised to leave the local tribes alone and means to break that promise; the Fort Tombstone vampires, her spirit brothers. She tolerates the Black Swords and watches Sir Jude and the giant for Xavier.', 'Civilization, technology and the White Man; Sir Bending River, the knight she deserted.', 'Young, lithe and earthy rather than beautiful, in traditional hides with beaded charms, hip-length black hair braided with fetishes, near-black burning eyes and a set jaw. Raised a Traditionalist on the Casper Preserve fighting demons, she took the place of a fallen knight beside Sir Bending River and trained as a Cyber-Knight, refusing energy weapons, modern armor and Cyber-Armor. Travel turned her bitter, voices began to guide her, and she left him; after a year alone she saw vampires as creatures of her own totem, begged to join them, and swore herself to Xavier, who made her the Black Swords'' guide.', 'Rifts World Book 28: Arzno - Vampire Incursion p.158-160');
